-- =========================================================
-- ESPETINHOS TREVIZAN - MOVIMENTO DE 05/10 A 17/10/2026
-- Arquivo 07
--
-- Execute DEPOIS dos scripts 01, 02, 03, 05 e 06.
--
-- O que este script faz (banco trevizan_espetinhos):
--  0) garante as mesas 11 a 16 e o produto 151, usados no
--     movimento (não altera nada se já existirem);
--  1) guarda uma cópia das tabelas de movimento em tabelas
--     backup_antes_07_* (para desfazer, se precisar);
--  2) apaga caixas, comandas, itens, pagamentos e movimentações
--     e grava o movimento de 05 a 17/10/2026, numerado em ordem
--     de data (caixa #1 = 05/10, comanda #1 = primeira de 05/10);
--  3) acerta o próximo número (AUTO_INCREMENT) de cada tabela.
--
-- Observação: os registros de 16 e 17/10/2026 (caixas 12 e 13)
-- são fictícios.
--
-- Não mexe em usuários, categorias nem no cardápio existente.
-- Execute o script inteiro de uma vez (Ctrl+Shift+Enter no Workbench).
-- =========================================================

USE trevizan_espetinhos;

-- ---------------------------------------------------------
-- 0) MESAS E PRODUTO USADOS NO MOVIMENTO
-- ---------------------------------------------------------
INSERT IGNORE INTO mesa (id_mesa, numero, status, ativo)
VALUES
    (11, 11, 'LIVRE', 1),
    (12, 12, 'LIVRE', 1),
    (13, 13, 'LIVRE', 1),
    (14, 14, 'LIVRE', 1),
    (15, 15, 'LIVRE', 1),
    (16, 16, 'LIVRE', 1);

-- Produto cadastrado direto na loja (aparece em 1 item da comanda #310).
-- Se ele já existir no seu banco, nada é alterado.
INSERT IGNORE INTO produto (id_produto, id_categoria, nome, descricao, preco, local_preparo, ativo)
VALUES (151, 6, 'Produto 151 (cadastrado na loja)', NULL, 12.00, 'COZINHA', 1);

-- ---------------------------------------------------------
-- 1) CÓPIA DE SEGURANÇA
-- ---------------------------------------------------------
DROP TABLE IF EXISTS backup_antes_07_caixa, backup_antes_07_comanda,
    backup_antes_07_item_comanda, backup_antes_07_pagamento,
    backup_antes_07_movimentacao_caixa;

CREATE TABLE backup_antes_07_caixa              AS SELECT * FROM caixa;
CREATE TABLE backup_antes_07_comanda            AS SELECT * FROM comanda;
CREATE TABLE backup_antes_07_item_comanda       AS SELECT * FROM item_comanda;
CREATE TABLE backup_antes_07_pagamento          AS SELECT * FROM pagamento;
CREATE TABLE backup_antes_07_movimentacao_caixa AS SELECT * FROM movimentacao_caixa;

-- ---------------------------------------------------------
-- 2) MOVIMENTO EM ORDEM DE DATA
-- ---------------------------------------------------------
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

DELETE FROM movimentacao_caixa WHERE id_movimentacao > 0;
DELETE FROM pagamento          WHERE id_pagamento > 0;
DELETE FROM item_comanda       WHERE id_item_comanda > 0;
DELETE FROM comanda            WHERE id_comanda > 0;
DELETE FROM caixa              WHERE id_caixa > 0;

