-- ---------------------------------------------------------
-- 3) PRÓXIMO NÚMERO DE CADA TABELA
-- ---------------------------------------------------------
ALTER TABLE caixa              AUTO_INCREMENT = 14;
ALTER TABLE comanda            AUTO_INCREMENT = 510;
ALTER TABLE item_comanda       AUTO_INCREMENT = 1441;
ALTER TABLE pagamento          AUTO_INCREMENT = 504;
ALTER TABLE movimentacao_caixa AUTO_INCREMENT = 507;

-- ---------------------------------------------------------
-- CONFERÊNCIA: deve mostrar 13 caixas, 509 comandas, 1440 itens,
-- 503 pagamentos e 506 movimentações
-- ---------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM caixa)              AS caixas,
    (SELECT COUNT(*) FROM comanda)            AS comandas,
    (SELECT COUNT(*) FROM item_comanda)       AS itens,
    (SELECT COUNT(*) FROM pagamento)          AS pagamentos,
    (SELECT COUNT(*) FROM movimentacao_caixa) AS movimentacoes;
